transforms.code:
try:
	if value is None:
		value = ''
	return value
except:
	return ''

db           = value["db"]
wkSelected   = value["wkSelected"]
filterStatus = value["filterStatus"]

logger = system.util.getLogger("WS-Check")

def _normalize_ip(ip):
	# Normaliza IPv6-mapped (p.ej. ::ffff:10.0.0.5) a IPv4
	if ip and ip.startswith("::ffff:"):
		return ip.split(":")[-1]
	return (ip or "").strip()

def _get_this_sessioninfo(self):
	sid = self.session.props.id
	for s in system.perspective.getSessionInfo():
		if s.get("id") == sid:
			return s
	return {}

# Si NO filtras, resolvemos por IP; si filtras, devolvemos wkSelected.
if not filterStatus:
	try:
		sinfo = _get_this_sessioninfo(self)
		ip = _normalize_ip(sinfo.get("clientAddress", ""))

		# SQL Server: SELECT TOP 1 ...
		sql = """
			SELECT TOP 1 ID, Description, Hostname
			FROM workstation
			WHERE IpAddress = ?
		"""
		ds = system.db.runPrepQuery(sql, [ip], db)

		if ds and ds.getRowCount() > 0:
			return int(ds.getValueAt(0, "ID"))
		else:
			logger.info("WS-Check: no se encontró workstation para IP=%s" % ip)
			return ip

	except Exception as e:
		logger.error("WS-Check error: %s" % e)
		return -1
else:
	return int(wkSelected or 0)

ds = value["ds"]        # Dataset
targetID = value["id"]  # El ID que estás buscando

# --- Buscar la fila donde la columna "ID" coincide ---
rowIndex = -1
for i in range(ds.getRowCount()):
    if ds.getValueAt(i, "ID") == targetID:
        rowIndex = i
        break

# --- Si lo encontró, obtén el valor que quieras (por nombre o índice) ---
if rowIndex != -1:
    valor = ds.getValueAt(rowIndex, "Name")  # o por nombre de columna: ds.getValueAt(rowIndex, "Description")
    if valor == 'ME Cominco':
    	valor = 'Cominco'
    if valor == 'Rejilladora':
    	    	valor = 'Rejilladoras'
else:
    valor = None  # No se encontró el ID

return valor

"""
Genera ejes, plots y pens dinámicos a partir de instancias que contienen UDTs hijas.
Lee automáticamente las unidades de ingeniería desde las tags CurrentValue.
Cada unidad genera su propio eje y su propio plot.
"""

from java.lang import String

# === INPUT: lista de instancias base ===
instances = value

# === 1️⃣ Inicializar estructuras ===
pens = []
unit_map = {}  # {unidad: índice de eje/plot}

# === 2️⃣ Escanear instancias ===
for inst in instances:
    pathSource = inst.get("pathSource", "")
    baseColor = inst.get("color", "#00bcd4")

    try:
        children = system.tag.browse(pathSource).getResults()
    except:
        children = []

    for child in children:
        if str(child['tagType']) != "UdtInstance":
            continue  # solo UDTs hijas

        childName = child['name']
        childPath = str(child['fullPath'])

        # Buscar el tag CurrentValue dentro de la UDT hija
        try:
            subTags = system.tag.browse(childPath).getResults()
        except:
            subTags = []

        for subTag in subTags:
            if subTag['name'] != "CurrentValue":
                continue

            currentPath = str(subTag['fullPath'])
            eng_unit = None

            # === 3️⃣ Detectar unidad de ingeniería ===
            for prop in ('.EngUnit', '.EngineeringUnits', '.Eng Units', '.Unit'):
                try:
                    result = system.tag.readBlocking([currentPath + prop])[0]
                    if result.quality.isGood() and result.value not in (None, "", " "):
                        eng_unit = str(result.value).strip()
                        break
                except:
                    continue

            if eng_unit is None:
                eng_unit = "default"

            # === 4️⃣ Crear ejes y plots únicos por unidad ===
            if eng_unit not in unit_map:
                idx = len(unit_map)
                unit_map[eng_unit] = idx

            plotIndex = unit_map[eng_unit]

            # === 5️⃣ Crear pen ===
            pen = {
                "name": childName,
                "visible": True,
                "enabled": True,
                "selectable": False,
                "axis": eng_unit,
                "plot": plotIndex,  # 👈 cada unidad tiene su propio plot
                "display": {
                    "type": "line",
                    "interpolation": "curveLinear",
                    "breakLine": True,
                    "radius": 3,
                    "styles": {
                        "normal": {
                            "stroke": {"color": baseColor, "width": 1, "opacity": 0.8},
                            "fill": {"color": baseColor, "opacity": 0.8},
                        },
                    },
                },
                "data": {
                    "source": currentPath,
                    "aggregateMode": "default",
                },
            }
            pens.append(pen)

# === 6️⃣ Crear ejes (uno por unidad) ===
axes = []
for unit in unit_map.keys():
    axis = {
        "name": unit,
        "position": "left",
        "width": 60,
        "color": "#757A7F",
        "dataFormat": "0,0.##",
        "range": {"auto": True, "min": "", "max": ""},
        "label": {
            "text": unit,
            "offset": 0,
            "font": {"color": "#757A7F", "size": 12},
            "style": {"classes": ""}
        },
        "tick": {
            "color": "#757A7F",
            "count": "Auto",
            "label": {
                "format": "Auto",
                "font": {"color": "#757A7F", "size": 10},
                "style": {"classes": ""}
            },
            "style": {"classes": ""}
        },
        "style": {"classes": ""}
    }
    axes.append(axis)

# === 7️⃣ Crear plots (uno por unidad) ===
plots = []
for _ in unit_map.keys():
    plots.append({
        "relativeWeight": 3,
        "color": "var(--neutral-10)",
        "markers": [],
        "style": {"classes": ""}
    })

# === 8️⃣ Asignar resultados ===
self.props.plots = plots
self.props.axes = axes
return pens

if value == []:
	value = False
else:
	value = True
return value
